// NIVEL 1: consultar primero el indice de archivos para saber CUALES son relevantes,
// despues filtrar la query de chunks por solo esos archivos.
const embRes = $input.first().json;
const body = $('Webhook Consulta').first().json.body || {};
const pregunta = body.pregunta || '';
const proyecto = body.proyecto || null;
const n_results = body.n_results || 5;
const usar_indice = body.usar_indice !== false; // default true

if (!embRes.data || !embRes.data[0]) {
  throw new Error(`Embedding response invalid: ${JSON.stringify(embRes).slice(0,300)}`);
}
const preguntaEmb = embRes.data[0].embedding;

// PASO 1: query al indice (top-10 archivos mas relevantes)
let archivosRelevantes = [];
let mapaArchivos = [];
if (usar_indice && $env.CHROMA_INDICE_ID) {
  try {
    const indicePayload = {
      query_embeddings: [preguntaEmb],
      n_results: 10,
      include: ['documents', 'metadatas', 'distances'],
    };
    if (proyecto) indicePayload.where = { proyecto };
    const idx = await this.helpers.httpRequest({
      method: 'POST',
      url: `http://localhost:8000/api/v2/tenants/default_tenant/databases/default_database/collections/${$env.CHROMA_INDICE_ID}/query`,
      headers: { 'Content-Type': 'application/json' },
      body: indicePayload,
      json: true,
    });
    const metas = (idx.metadatas && idx.metadatas[0]) || [];
    const dists = (idx.distances && idx.distances[0]) || [];
    // Filtrar a archivos con distancia razonable (< umbral) - umbral generoso para no perder cosas
    const UMBRAL = 1.5;
    for (let i = 0; i < metas.length; i++) {
      if (dists[i] !== undefined && dists[i] > UMBRAL) continue;
      archivosRelevantes.push(metas[i].archivo);
      mapaArchivos.push({
        archivo: metas[i].archivo,
        tema: metas[i].tema,
        resumen: metas[i].resumen,
        entidades: metas[i].entidades,
        distancia: Number((dists[i] || 0).toFixed(3)),
        n_chunks: metas[i].n_chunks,
      });
    }
  } catch (e) {
    // Si el indice falla, seguimos sin filtro (fallback al RAG plano)
    archivosRelevantes = [];
    mapaArchivos = [];
  }
}

// PASO 2: construir query a chunks con filtro de archivos (si hay)
const payload = {
  query_embeddings: [preguntaEmb],
  n_results,
  include: ['documents', 'metadatas', 'distances']
};
const whereConds = [];
if (proyecto) whereConds.push({ proyecto });
if (archivosRelevantes.length > 0) {
  // Chroma soporta $in para filtros
  whereConds.push({ archivo: { '$in': archivosRelevantes } });
}
if (whereConds.length === 1) payload.where = whereConds[0];
else if (whereConds.length > 1) payload.where = { '$and': whereConds };

return [{ json: { pregunta, proyecto, n_results, chroma_payload: payload, mapa_archivos: mapaArchivos, usar_indice } }];

// Procesa chunks de Chroma + detecta contradicciones entre ellos + opcionalmente activa web search.
const chromaRes = $input.first().json;
const body = $('Webhook Consulta').first().json.body || {};
const pregunta = body.pregunta || '';
const proyecto = body.proyecto || null;
const webSearch = body.web_search === true;

const ids = (chromaRes.ids && chromaRes.ids[0]) || [];
const docs = (chromaRes.documents && chromaRes.documents[0]) || [];
const metas = (chromaRes.metadatas && chromaRes.metadatas[0]) || [];
const dists = (chromaRes.distances && chromaRes.distances[0]) || [];

// Si no hay chunks Y no se pidio web search -> respuesta fallback
if (ids.length === 0 && !webSearch) {
  return [{ json: {
    skip_llm: true,
    pregunta, proyecto,
    respuesta: 'No encontre eso en tus fuentes. Activa la busqueda web para complementar.',
    citas: [], contradicciones: [], modo: 'real', web_search: false
  }}];
}

const getPagina = (m) => m?.pagina ?? m?.pagina_aprox ?? 1;
const isExact = (m) => m?.pagina !== undefined && m?.pagina !== null;

const citas = ids.map((id, i) => ({
  archivo: metas[i]?.archivo,
  pagina: getPagina(metas[i]),
  pagina_exacta: isExact(metas[i]),
  total_paginas: metas[i]?.total_paginas,
  chunk_index: metas[i]?.chunk_index,
  proyecto: metas[i]?.proyecto,
  fecha: metas[i]?.fecha,
  distancia: Number((dists[i] || 0).toFixed(4)),
  extracto: (docs[i] || '').slice(0, 600)
}));

const contexto = ids.map((id, i) => {
  const m = metas[i] || {};
  const pageHint = isExact(m) ? `pag ${getPagina(m)}` : `pag ~${getPagina(m)}`;
  const fechaHint = m.fecha ? ` | fecha: ${m.fecha}` : '';
  return `[${i+1}] (archivo: ${m.archivo}, ${pageHint}/${m.total_paginas}${fechaHint})\n${docs[i]}`;
}).join('\n\n---\n\n');

// === DETECTAR CONTRADICCIONES (1 LLM call, gpt-4o-mini barato) ===
let contradicciones = [];
if (ids.length >= 2) {
  const detectorSystem = `Sos un detector de contradicciones entre pasajes de fuentes.
Te paso N pasajes recuperados (cada uno con su archivo y fecha si la tiene).
Tu tarea: identificar CUALQUIER PAR de pasajes que se contradigan entre si — afirman cosas mutuamente excluyentes sobre el mismo hecho (numeros distintos, fechas distintas, conclusiones opuestas, etc.).

IMPORTANTE: solo marca contradicciones REALES (no ambiguedades de redaccion). Si un pasaje habla de "Q1 2024" y otro de "Q1 2025", NO es contradiccion (hablan de momentos distintos). Si dos pasajes dan distintos valores para EL MISMO hecho en el MISMO contexto temporal, SI lo es.

Devolve JSON exacto:
{
  "contradicciones": [
    {
      "pasaje_a": 1,
      "pasaje_b": 3,
      "sobre": "que tema/hecho exactamente se contradicen",
      "a_dice": "que afirma el pasaje A",
      "b_dice": "que afirma el pasaje B",
      "severidad": "alta" | "media" | "baja"
    }
  ]
}
Si no hay contradicciones, devolve { "contradicciones": [] }.`;
  const detectorUser = `Pasajes a analizar:\n\n${contexto}`;
  try {
    const detRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        'Authorization': `Bearer ${$env.OPENROUTER_API_KEY}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'http://localhost',
        'X-Title': 'CoWorkerIA Detector',
      },
      body: {
        model: 'openai/gpt-4o-mini',
        messages: [
          { role: 'system', content: detectorSystem },
          { role: 'user', content: detectorUser },
        ],
        max_tokens: 800,
        temperature: 0,
      },
      json: true,
    });
    const raw = detRes.choices?.[0]?.message?.content || '{}';
    let parsed;
    try { parsed = JSON.parse(raw); }
    catch {
      const cleaned = raw.replace(/^```(?:json)?\s*/gm, '').replace(/```\s*$/gm, '').trim();
      try { parsed = JSON.parse(cleaned); } catch { parsed = {}; }
    }
    contradicciones = Array.isArray(parsed.contradicciones) ? parsed.contradicciones.map(c => ({
      pasaje_a: c.pasaje_a,
      pasaje_b: c.pasaje_b,
      sobre: c.sobre || '',
      a_dice: c.a_dice || '',
      b_dice: c.b_dice || '',
      severidad: c.severidad || 'media',
      cita_a: citas[c.pasaje_a - 1] ? `${citas[c.pasaje_a - 1].archivo}, pag ${citas[c.pasaje_a - 1].pagina}` : '',
      cita_b: citas[c.pasaje_b - 1] ? `${citas[c.pasaje_b - 1].archivo}, pag ${citas[c.pasaje_b - 1].pagina}` : '',
    })) : [];
    // Capturar usage del detector para loguear
    var contradicciones_usage = detRes.usage || null;
  } catch (e) {
    contradicciones = [];
    var contradicciones_usage = null;
  }
} else {
  var contradicciones_usage = null;
}

const contradHint = contradicciones.length > 0
  ? `\n\nIMPORTANTE: Detectamos contradicciones entre los pasajes:\n${contradicciones.map((c, i) => `(${i+1}) ${c.sobre}: pasaje [${c.pasaje_a}] dice "${c.a_dice}" vs pasaje [${c.pasaje_b}] dice "${c.b_dice}" [severidad: ${c.severidad}]`).join('\n')}\n\nMenciona estas contradicciones explicitamente en tu respuesta y deja la decision al usuario.`
  : '';

const webHint = webSearch
  ? `\n\nADEMAS: Tienes acceso a busqueda web para complementar lo que NO esta en los pasajes del usuario. Cuando uses informacion de la web, citala como [web: titulo del articulo]. Diferencia claramente lo que viene de las fuentes del usuario vs lo que viene de la web.`
  : '';

const system = `Eres CoWorkerIA, asistente de conocimiento del usuario.${webSearch ? ' Tienes dos fuentes: los pasajes del usuario + busqueda web. Privilegia siempre los pasajes del usuario.' : ' Respondes EXCLUSIVAMENTE basandote en los pasajes que se te entregan a continuacion.'}\n\nREGLAS NO NEGOCIABLES:\n1. NUNCA inventes informacion. ${webSearch ? 'Si ni los pasajes ni la web tienen la respuesta, di: "No encontre eso".' : 'Si los pasajes no contienen la respuesta, di exactamente: "No encontre eso en tus fuentes."'}\n2. SIEMPRE cita la fuente: pasajes del usuario como [archivo, pag. N]; informacion de la web como [web: titulo].\n3. Se conciso y directo. Sin introducciones ni cierres innecesarios.\n4. Si los pasajes son contradictorios entre si (te marcaremos las contradicciones detectadas), senalalas explicitamente al usuario y dejale la decision.\n5. Tu rol incluye ser un sparring critico: si detectas una debilidad o supuesto no verificado en la pregunta del usuario, comentalo brevemente al final bajo el encabezado "Observacion critica:".${webHint}`;

// Obtener mapa de archivos (NIVEL 1) del nodo anterior si esta disponible
const prevData = $('Build Chroma query').first().json;
const mapaArchivos = prevData?.mapa_archivos || [];
const mapaBlock = mapaArchivos.length > 0
  ? `\n\n[MAPA DE ARCHIVOS] (resumenes de los archivos mas relevantes en el cerebro del usuario, ordenados por similitud con la pregunta):\n${mapaArchivos.slice(0, 8).map((m, i) => `(${i+1}) ${m.archivo} - ${m.tema}\n    resumen: ${m.resumen}\n    entidades clave: ${m.entidades}`).join('\n\n')}\n\nPodes referenciar archivos del mapa aunque no esten en los pasajes recuperados (ej: 'mira tambien X.py para mas detalle').`
  : '';

const pasajesBlock = ids.length > 0
  ? `Pasajes recuperados de tus fuentes (chunks especificos extraidos de los archivos del mapa):\n\n${contexto}${contradHint}${mapaBlock}`
  : `No hay pasajes especificos recuperados.${mapaBlock || ' Usa solo la busqueda web.'}`;

const user = `Pregunta del usuario: ${pregunta}\n\n${pasajesBlock}\n\nResponde${webSearch ? ' combinando pasajes (si los hay) con busqueda web cuando ayude' : ' usando solo estos pasajes'}.`;

const llmPayload = {
  model: $env.LLM_MODEL || 'anthropic/claude-sonnet-4',
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: user }
  ],
  max_tokens: 1500,
  temperature: 0.2
};

if (webSearch) {
  llmPayload.plugins = [{ id: 'web', max_results: 5 }];
}

return [{ json: { skip_llm: false, pregunta, proyecto, citas, contradicciones, contradicciones_usage, mapa_archivos: mapaArchivos, llm_payload: llmPayload, modo: 'real', web_search: webSearch }}];

const llmRes = $input.first().json;
const prev = $('Build LLM prompt + Detectar contradicciones').first().json;
const msg = llmRes.choices?.[0]?.message || {};
const respuesta = msg.content || '(LLM no devolvio respuesta)';

// Extraer citas web del annotations field (OpenRouter web plugin)
const webCitas = [];
for (const a of (msg.annotations || [])) {
  if (a.type === 'url_citation' && a.url_citation) {
    webCitas.push({
      url: a.url_citation.url,
      titulo: a.url_citation.title || a.url_citation.url,
      extracto: (a.url_citation.content || '').slice(0, 400),
    });
  }
}

return [{ json: {
  pregunta: prev.pregunta,
  proyecto: prev.proyecto,
  respuesta,
  citas: prev.citas,
  citas_web: webCitas,
  contradicciones: prev.contradicciones || [],
  mapa_archivos: prev.mapa_archivos || [],
  modo: prev.modo,
  web_search: prev.web_search === true,
  usage: llmRes.usage,
  usages: [
    ...(prev.contradicciones_usage ? [{ tipo: 'consulta_contradicciones', modelo: 'openai/gpt-4o-mini', ...prev.contradicciones_usage }] : []),
    { tipo: 'chat', modelo: llmRes.model || ($env.LLM_MODEL || 'anthropic/claude-sonnet-4'), ...llmRes.usage }
  ]
}}];
